-- ═══════════ 20261119150000_schema.sql ═══════════

-- Pull Up · 1 of 5 · tables, constraints, indexes
--
-- Conventions
--   * Timestamps are timestamptz (stored in UTC). The app displays Asia/Jerusalem.
--   * The browser can only SELECT (through row level security). Every write goes
--     through a function in 20261119150200_write_functions.sql.
--   * "Full", "started", "completed" and "expired" are derived from the rows below,
--     never stored twice.

create schema if not exists private;

-- ───────────────────────── validation helpers ─────────────────────────

create or replace function private.valid_avatar(a jsonb)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select jsonb_typeof(a) = 'object'
    and not exists (
      select 1 from jsonb_object_keys(a) k
      where k not in ('skin', 'hair', 'hairColor', 'bg', 'shirt', 'beard', 'glasses')
    )
    and coalesce(a ->> 'skin', '') ~ '^[1-5]$'
    and coalesce(a ->> 'hair', '') in ('short', 'buzz', 'long', 'bob', 'bun', 'curly', 'hijab')
    and coalesce(a ->> 'hairColor', '') ~ '^#[0-9a-fA-F]{6}$'
    and coalesce(a ->> 'bg', '') ~ '^#[0-9a-fA-F]{6}$'
    and coalesce(a ->> 'shirt', '') ~ '^#[0-9a-fA-F]{6}$'
    and coalesce(jsonb_typeof(a -> 'beard'), 'boolean') = 'boolean'
    and coalesce(jsonb_typeof(a -> 'glasses'), 'boolean') = 'boolean'
$$;

create or replace function private.known_languages()
returns text[] language sql immutable set search_path = '' as $$
  select array['he', 'en', 'ar', 'ru', 'fr', 'es', 'de', 'am']
$$;

create or replace function private.known_types()
returns text[] language sql immutable set search_path = '' as $$
  select array['bar', 'restaurant', 'boardgames', 'sports', 'class', 'other']
$$;

create or replace function private.touch_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end
$$;

-- ───────────────────────── people ─────────────────────────

-- What other people are allowed to see: first name, illustrated avatar, age range, languages.
-- The row is never deleted. Deleting an account blanks it (see delete_account).
create table public.profiles (
  id            uuid primary key,              -- same value as auth.users.id; no FK so the blanked row can outlive the sign-in
  first_name    text not null default '' check (char_length(first_name) <= 30),
  avatar        jsonb not null default '{}'::jsonb,
  age_range     text check (age_range in ('18-24', '25-29', '30-34', '35-39', '40-49', '50-59', '60+')),
  languages     text[] not null default '{}'
                check (languages <@ private.known_languages() and cardinality(languages) <= 6),
  onboarded_at  timestamptz,
  deleted_at    timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint profiles_complete_unless_deleted check (
    deleted_at is not null
    or (
      char_length(btrim(first_name)) >= 1
      and age_range is not null
      and cardinality(languages) >= 1
      and private.valid_avatar(avatar)
    )
  )
);

create trigger profiles_touch before update on public.profiles
  for each row execute function private.touch_updated_at();

-- Only the owner can read this row. Nothing here is ever sent to another user.
create table public.account_private (
  user_id              uuid primary key references public.profiles (id) on delete cascade,
  gender               text check (gender in ('woman', 'man', 'nonbinary')),   -- null = not stated; only ever shown as a group total
  interests            text[] not null default '{}'
                       check (interests <@ private.known_types() and cardinality(interests) <= 6),
  locale               text not null default 'en' check (locale in ('en', 'he')),
  adult_declared_at    timestamptz not null,   -- self-declared "I am 18 or older"
  terms_version        text not null,
  terms_accepted_at    timestamptz not null,
  technion_email       text unique check (technion_email = lower(technion_email)),
  technion_verified_at timestamptz,            -- no function sets this yet: the badge stays off until verification really exists
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

create trigger account_private_touch before update on public.account_private
  for each row execute function private.touch_updated_at();

create table public.admins (
  user_id    uuid primary key references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now()
);

create table public.blocks (
  blocker_id uuid not null references public.profiles (id),
  blocked_id uuid not null references public.profiles (id),
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id),
  check (blocker_id <> blocked_id)
);
create index blocks_blocked_idx on public.blocks (blocked_id);

-- ───────────────────────── spots ─────────────────────────

create table public.spots (
  id             uuid primary key default gen_random_uuid(),
  host_id        uuid not null references public.profiles (id),
  kind           text not null check (kind in ('missing_someone', 'start_plan')),
  type           text not null check (type = any (private.known_types())),
  title          text not null check (char_length(title) between 3 and 60),
  venue_name     text not null check (char_length(venue_name) between 2 and 80),
  address        text not null check (char_length(address) between 3 and 160),
  lat            double precision,
  lng            double precision,
  city           text not null default 'haifa' check (city in ('haifa')),
  starts_at      timestamptz not null,
  ends_at        timestamptz not null,
  -- Friends who are coming but are not Pull Up users. Numbers only, as told by the host.
  friends_count  smallint not null default 0 check (friends_count between 0 and 10),
  friends_women  smallint not null default 0 check (friends_women >= 0),
  friends_men    smallint not null default 0 check (friends_men >= 0),
  friends_other  smallint not null default 0 check (friends_other >= 0),
  places         smallint not null check (places between 1 and 8),   -- total places for people joining through Pull Up
  languages      text[] not null
                 check (languages <@ private.known_languages() and cardinality(languages) between 1 and 4),
  cost_note      text not null default '' check (char_length(cost_note) <= 120),
  needs_booking  boolean not null default false,
  booking_note   text not null default '' check (char_length(booking_note) <= 200),
  host_note      text not null default '' check (char_length(host_note) <= 300),
  cancelled_at   timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint spots_time_order check (ends_at > starts_at and ends_at <= starts_at + interval '12 hours'),
  -- Written so that a half-filled pair is rejected: a CHECK passes on NULL.
  constraint spots_coordinates check (
    (lat is null) = (lng is null)
    and (lat is null or (lat between 29.0 and 33.6 and lng between 34.0 and 36.0))
  ),
  constraint spots_friends_mix check (friends_women + friends_men + friends_other <= friends_count),
  constraint spots_kind_matches_friends check (
    (kind = 'missing_someone' and friends_count >= 1)
    or (kind = 'start_plan' and friends_count = 0)
  )
);
create index spots_discovery_idx on public.spots (city, starts_at) where cancelled_at is null;
create index spots_host_idx on public.spots (host_id, starts_at);
create index spots_ends_idx on public.spots (ends_at);

create trigger spots_touch before update on public.spots
  for each row execute function private.touch_updated_at();

-- Readable only by the host and by members who are currently in the group.
create table public.spot_private (
  spot_id      uuid primary key references public.spots (id) on delete cascade,
  find_us_hint text not null default '' check (char_length(find_us_hint) <= 200)
);

-- ───────────────────────── requests and memberships ─────────────────────────

create table public.join_requests (
  id           uuid primary key default gen_random_uuid(),
  spot_id      uuid not null references public.spots (id) on delete cascade,
  requester_id uuid not null references public.profiles (id),
  message      text not null default '' check (char_length(message) <= 200),
  status       text not null default 'pending'
               check (status in ('pending', 'accepted', 'declined', 'withdrawn', 'expired')),
  created_at   timestamptz not null default now(),
  decided_at   timestamptz,
  updated_at   timestamptz not null default now()
);
-- At most one live request per person per spot.
create unique index join_requests_one_live on public.join_requests (spot_id, requester_id)
  where status in ('pending', 'accepted');
create index join_requests_spot_idx on public.join_requests (spot_id, status);
create index join_requests_requester_idx on public.join_requests (requester_id, status, created_at);

create trigger join_requests_touch before update on public.join_requests
  for each row execute function private.touch_updated_at();

-- People who joined through Pull Up. The host is spots.host_id and has no row here.
create table public.memberships (
  spot_id    uuid not null references public.spots (id) on delete cascade,
  user_id    uuid not null references public.profiles (id),
  request_id uuid not null unique references public.join_requests (id) on delete cascade,
  status     text not null default 'active' check (status in ('active', 'left', 'removed')),
  joined_at  timestamptz not null default now(),
  ended_at   timestamptz,
  primary key (spot_id, user_id),          -- one membership per person per spot, ever
  check ((status = 'active') = (ended_at is null))
);
create index memberships_user_idx on public.memberships (user_id, status);
create index memberships_active_idx on public.memberships (spot_id) where status = 'active';

-- ───────────────────────── chat and notifications ─────────────────────────

create table public.messages (
  id         uuid primary key default gen_random_uuid(),
  spot_id    uuid not null references public.spots (id) on delete cascade,
  sender_id  uuid not null references public.profiles (id),
  body       text not null,
  client_id  uuid not null,                -- made by the phone; a retried send reuses it and cannot duplicate
  created_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (sender_id, client_id),
  check (
    (deleted_at is not null and body = '')
    or (deleted_at is null and char_length(body) between 1 and 1000)
  )
);
create index messages_spot_idx on public.messages (spot_id, created_at, id);
create index messages_sender_idx on public.messages (sender_id, created_at);

-- A notification stores only its type and what it points at. Names and text are read
-- separately through the normal access rules, so a notification can never leak them.
create table public.notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade,
  type       text not null check (type in (
               'request_received', 'request_accepted', 'request_declined', 'request_expired',
               'spot_cancelled', 'spot_changed', 'place_opened', 'member_removed',
               'new_message', 'rating_open')),
  spot_id    uuid not null references public.spots (id) on delete cascade,
  request_id uuid references public.join_requests (id) on delete cascade,
  created_at timestamptz not null default now(),
  read_at    timestamptz
);
create index notifications_user_idx on public.notifications (user_id, created_at desc);
-- One unread "new messages" notification per chat, however many messages arrive.
create unique index notifications_one_unread_chat on public.notifications (user_id, spot_id)
  where type = 'new_message' and read_at is null;
create unique index notifications_rating_open_once on public.notifications (user_id, spot_id)
  where type = 'rating_open';
create unique index notifications_request_once on public.notifications (user_id, request_id, type)
  where request_id is not null;

-- ───────────────────────── ratings and reports ─────────────────────────

create table public.ratings (
  id                  uuid primary key default gen_random_uuid(),
  spot_id             uuid not null references public.spots (id) on delete cascade,
  rater_id            uuid not null references public.profiles (id),
  ratee_id            uuid not null references public.profiles (id),
  stars               smallint not null check (stars between 1 and 5),
  felt_safe           text check (felt_safe in ('yes', 'mostly', 'no')),
  matched_description text check (matched_description in ('yes', 'partly', 'no')),
  tags                text[] not null default '{}'
                      check (tags <@ array['welcoming', 'easy_to_find', 'good_conversation', 'as_described',
                                           'friendly', 'on_time', 'awkward', 'no_show']
                             and cardinality(tags) <= 6),
  created_at          timestamptz not null default now(),
  unique (spot_id, rater_id, ratee_id),
  check (rater_id <> ratee_id)
);
create index ratings_ratee_idx on public.ratings (ratee_id);

-- Private. Readable only by admins (and in the Supabase dashboard).
create table public.reports (
  id               uuid primary key default gen_random_uuid(),
  reporter_id      uuid not null references public.profiles (id),
  reported_user_id uuid references public.profiles (id),
  spot_id          uuid references public.spots (id) on delete set null,
  reason           text not null check (reason in (
                     'not_who_they_said', 'made_uncomfortable', 'pressure', 'wrong_place_or_time',
                     'harassment', 'fake_or_spam', 'other')),
  details          text not null default '' check (char_length(details) <= 1000),
  status           text not null default 'open' check (status in ('open', 'reviewing', 'closed')),
  admin_note       text not null default '',
  created_at       timestamptz not null default now(),
  check (reported_user_id is not null or spot_id is not null),
  check (reported_user_id is null or reported_user_id <> reporter_id)
);
create index reports_created_idx on public.reports (created_at);
create index reports_reporter_idx on public.reports (reporter_id, created_at);


-- ═══════════ 20261119150100_access_rules.sql ═══════════

-- Pull Up · 2 of 5 · who can read what
--
-- Row level security is on for every table. The browser role ("authenticated") gets
-- SELECT only, and only on the rows the policies below allow. Logged-out visitors
-- ("anon") get nothing at all.
--
-- The helper functions live in the "private" schema, which the API does not expose.
-- They run as the table owner so that one policy can look at another table without
-- recursing into that table's own policy.

-- ───────────────────────── helpers used by policies ─────────────────────────

create or replace function private.is_onboarded(p_user uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.profiles p
    where p.id = p_user and p.onboarded_at is not null and p.deleted_at is null
  )
$$;

create or replace function private.is_admin(p_user uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.admins a where a.user_id = p_user)
$$;

create or replace function private.blocked_between(p_a uuid, p_b uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.blocks b
    where (b.blocker_id = p_a and b.blocked_id = p_b)
       or (b.blocker_id = p_b and b.blocked_id = p_a)
  )
$$;

create or replace function private.is_host(p_spot uuid, p_user uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.spots s where s.id = p_spot and s.host_id = p_user)
$$;

create or replace function private.is_active_member(p_spot uuid, p_user uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.memberships m
    where m.spot_id = p_spot and m.user_id = p_user and m.status = 'active'
  )
$$;

-- Host, or a member who is in the group right now.
create or replace function private.is_participant(p_spot uuid, p_user uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select private.is_host(p_spot, p_user) or private.is_active_member(p_spot, p_user)
$$;

-- Has this person ever asked to join, or been a member of, this spot?
-- A withdrawn request does not count: the person took it back.
create or replace function private.has_history(p_spot uuid, p_user uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
           select 1 from public.memberships m where m.spot_id = p_spot and m.user_id = p_user
         )
      or exists (
           select 1 from public.join_requests r
           where r.spot_id = p_spot and r.requester_id = p_user and r.status <> 'withdrawn'
         )
$$;

-- Was this person in the group when the plan started? Used for ratings and "plans joined".
create or replace function private.was_member_at_start(p_spot uuid, p_user uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from public.memberships m
    join public.spots s on s.id = m.spot_id
    where m.spot_id = p_spot
      and m.user_id = p_user
      and m.joined_at <= s.starts_at
      and (m.status = 'active' or m.ended_at > s.starts_at)
  )
$$;

-- The one definition of "may this person see this spot".
--   * the host always can
--   * nobody can if either side blocked the other
--   * everyone else can until the plan ends (so a shared link shows "started" or
--     "cancelled" instead of nothing), and afterwards only people who were involved
create or replace function private.can_see_spot(p_spot uuid, p_user uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select private.is_onboarded(p_user) and exists (
    select 1 from public.spots s
    where s.id = p_spot
      and (
        s.host_id = p_user
        or (
          not private.blocked_between(s.host_id, p_user)
          and (s.ends_at > now() or private.has_history(s.id, p_user))
        )
      )
  )
$$;

-- May p_user see p_target's public profile (first name, avatar, age range, languages)?
--   * yourself: always
--   * a host: while they have a plan you can see
--   * someone who asked to join, or joined, your plan
--   * someone in the same group as you
-- The last three stop 30 days after the plan ends.
create or replace function private.can_see_profile(p_target uuid, p_user uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select p_target = p_user
    or (
      private.is_onboarded(p_user)
      and not private.blocked_between(p_target, p_user)
      and (
        exists (
          select 1 from public.spots s
          where s.host_id = p_target
            and (
              s.ends_at > now()
              or (s.ends_at > now() - interval '30 days' and private.has_history(s.id, p_user))
            )
        )
        or exists (
          select 1 from public.spots s
          where s.host_id = p_user
            and s.ends_at > now() - interval '30 days'
            and private.has_history(s.id, p_target)
        )
        or exists (
          select 1
          from public.memberships mine
          join public.memberships theirs on theirs.spot_id = mine.spot_id
          join public.spots s on s.id = mine.spot_id
          where mine.user_id = p_user and mine.status = 'active'
            and theirs.user_id = p_target and theirs.status = 'active'
            and s.ends_at > now() - interval '30 days'
        )
      )
    )
$$;

-- ───────────────────────── row level security ─────────────────────────

alter table public.profiles        enable row level security;
alter table public.account_private enable row level security;
alter table public.admins          enable row level security;
alter table public.blocks          enable row level security;
alter table public.spots           enable row level security;
alter table public.spot_private    enable row level security;
alter table public.join_requests   enable row level security;
alter table public.memberships     enable row level security;
alter table public.messages        enable row level security;
alter table public.notifications   enable row level security;
alter table public.ratings         enable row level security;
alter table public.reports         enable row level security;

create policy profiles_read on public.profiles
  for select to authenticated
  using (private.can_see_profile(id, (select auth.uid())));

create policy account_private_read_own on public.account_private
  for select to authenticated
  using (user_id = (select auth.uid()));

-- admins: no policy, so nobody reads it through the API.

create policy blocks_read_own on public.blocks
  for select to authenticated
  using (blocker_id = (select auth.uid()));

create policy spots_read on public.spots
  for select to authenticated
  using (
    private.is_onboarded((select auth.uid()))
    and (
      host_id = (select auth.uid())
      or (
        not private.blocked_between(host_id, (select auth.uid()))
        and (ends_at > now() or private.has_history(id, (select auth.uid())))
      )
    )
  );

create policy spot_private_read on public.spot_private
  for select to authenticated
  using (
    private.is_onboarded((select auth.uid()))
    and private.is_participant(spot_id, (select auth.uid()))
  );

-- The requester sees their own request. The host sees requests for their spot,
-- unless one of the two blocked the other.
create policy join_requests_read on public.join_requests
  for select to authenticated
  using (
    private.is_onboarded((select auth.uid()))
    and (
      requester_id = (select auth.uid())
      or (
        private.is_host(spot_id, (select auth.uid()))
        and not private.blocked_between(requester_id, (select auth.uid()))
      )
    )
  );

-- You see your own membership, the host sees all of them, and members who are in
-- the group right now see the others who are in it right now.
create policy memberships_read on public.memberships
  for select to authenticated
  using (
    private.is_onboarded((select auth.uid()))
    and (
      user_id = (select auth.uid())
      or private.is_host(spot_id, (select auth.uid()))
      or (status = 'active' and private.is_active_member(spot_id, (select auth.uid())))
    )
  );

-- Only the host and current members read the chat, and never a message from
-- someone they blocked or who blocked them.
create policy messages_read on public.messages
  for select to authenticated
  using (
    private.is_onboarded((select auth.uid()))
    and private.is_participant(spot_id, (select auth.uid()))
    and not private.blocked_between(sender_id, (select auth.uid()))
  );

create policy notifications_read_own on public.notifications
  for select to authenticated
  using (user_id = (select auth.uid()));

-- You can read the ratings you gave. Nobody reads the individual ratings they received.
create policy ratings_read_own_given on public.ratings
  for select to authenticated
  using (rater_id = (select auth.uid()));

-- Reports: admins only. The person who sent a report cannot read it back, and the
-- person it is about never sees it.
create policy reports_admin_read on public.reports
  for select to authenticated
  using (private.is_admin((select auth.uid())));

create policy reports_admin_update on public.reports
  for update to authenticated
  using (private.is_admin((select auth.uid())))
  with check (private.is_admin((select auth.uid())));

-- ───────────────────────── grants ─────────────────────────
-- Start from nothing, then add exactly what is needed.

revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;

grant select on
  public.profiles,
  public.account_private,
  public.blocks,
  public.spots,
  public.spot_private,
  public.join_requests,
  public.memberships,
  public.messages,
  public.notifications,
  public.ratings,
  public.reports
to authenticated;

grant update (status, admin_note) on public.reports to authenticated;   -- still gated by reports_admin_update

-- Policies call the helpers as the signed-in role, so it needs to reach them.
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;
revoke execute on all functions in schema private from public, anon;
grant execute on all functions in schema private to authenticated;


-- ═══════════ 20261119150200_write_functions.sql ═══════════

-- Pull Up · 3 of 5 · every write
--
-- The browser cannot INSERT, UPDATE or DELETE any table. It calls these functions,
-- and each one checks who is calling and whether the change is allowed right now.
--
-- Errors are raised with SQLSTATE P0001 and a short code as the message
-- (for example 'spot_full'). The app translates the code; it never shows it raw.
--
-- Locking: anything that changes who is in a group first locks that spot's row.
-- That makes "is there a place left?" and "take the place" one step, so two accepts
-- for the last place cannot both succeed.

-- ───────────────────────── internal helpers ─────────────────────────

create or replace function private.terms_version()
returns text language sql immutable set search_path = '' as $$ select '2026-11' $$;

-- One-line text: no control or text-direction-override characters, single spaces.
create or replace function private.clean_line(p text)
returns text language sql immutable set search_path = '' as $$
  select btrim(regexp_replace(
           regexp_replace(coalesce(p, ''), '[\u0001-\u001F\u007F‎‏‪-‮⁦-⁩]', ' ', 'g'),
           '\s+', ' ', 'g'))
$$;

-- Multi-line text: keeps line breaks, drops other control and direction-override characters.
create or replace function private.clean_text(p text)
returns text language sql immutable set search_path = '' as $$
  select btrim(regexp_replace(coalesce(p, ''), '[\u0001-\u0008\u000B-\u001F\u007F‪-‮⁦-⁩]', '', 'g'))
$$;

-- The signed-in, onboarded caller. Everything except onboarding itself starts here.
create or replace function private.require_user()
returns uuid language plpgsql stable security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception using errcode = 'P0001', message = 'not_signed_in';
  end if;
  if not private.is_onboarded(v_uid) then
    raise exception using errcode = 'P0001', message = 'not_onboarded';
  end if;
  return v_uid;
end
$$;

-- Serialises one person's rate-limited actions so the limits below are exact.
create or replace function private.lock_user(p_user uuid)
returns void language sql security definer set search_path = '' as $$
  select pg_advisory_xact_lock(hashtextextended('pull-up-user:' || p_user::text, 0))
$$;

create or replace function private.notify(p_user uuid, p_type text, p_spot uuid, p_request uuid default null)
returns void language sql security definer set search_path = '' as $$
  insert into public.notifications (user_id, type, spot_id, request_id)
  select p_user, p_type, p_spot, p_request
  where private.is_onboarded(p_user)
  on conflict do nothing
$$;

create or replace function private.active_member_count(p_spot uuid)
returns integer language sql stable security definer set search_path = '' as $$
  select count(*)::integer from public.memberships m where m.spot_id = p_spot and m.status = 'active'
$$;

-- ───────────────────────── account ─────────────────────────

create or replace function public.complete_onboarding(
  p_first_name    text,
  p_avatar        jsonb,
  p_age_range     text,
  p_languages     text[],
  p_gender        text,
  p_interests     text[],
  p_locale        text,
  p_is_adult      boolean,
  p_terms_version text
) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid  uuid := auth.uid();
  v_name text := private.clean_line(p_first_name);
begin
  if v_uid is null then
    raise exception using errcode = 'P0001', message = 'not_signed_in';
  end if;
  if p_is_adult is not true then
    raise exception using errcode = 'P0001', message = 'adult_required';
  end if;
  if p_terms_version is distinct from private.terms_version() then
    raise exception using errcode = 'P0001', message = 'terms_outdated';
  end if;
  if char_length(v_name) not between 1 and 30 or not private.valid_avatar(p_avatar) then
    raise exception using errcode = 'P0001', message = 'invalid_profile';
  end if;
  if exists (select 1 from public.profiles where id = v_uid and deleted_at is not null) then
    raise exception using errcode = 'P0001', message = 'account_deleted';
  end if;

  insert into public.profiles (id, first_name, avatar, age_range, languages, onboarded_at)
  values (v_uid, v_name, p_avatar, p_age_range, coalesce(p_languages, '{}'), now())
  on conflict (id) do update
    set first_name   = excluded.first_name,
        avatar       = excluded.avatar,
        age_range    = excluded.age_range,
        languages    = excluded.languages,
        onboarded_at = coalesce(public.profiles.onboarded_at, excluded.onboarded_at);

  insert into public.account_private
    (user_id, gender, interests, locale, adult_declared_at, terms_version, terms_accepted_at)
  values
    (v_uid, nullif(p_gender, ''), coalesce(p_interests, '{}'), coalesce(p_locale, 'en'), now(), p_terms_version, now())
  on conflict (user_id) do update
    set gender            = excluded.gender,
        interests         = excluded.interests,
        locale            = excluded.locale,
        terms_version     = excluded.terms_version,
        terms_accepted_at = case
                              when public.account_private.terms_version = excluded.terms_version
                              then public.account_private.terms_accepted_at
                              else excluded.terms_accepted_at
                            end;
end
$$;

create or replace function public.update_profile(
  p_first_name text,
  p_avatar     jsonb,
  p_age_range  text,
  p_languages  text[],
  p_gender     text,
  p_interests  text[]
) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid  uuid := private.require_user();
  v_name text := private.clean_line(p_first_name);
begin
  if char_length(v_name) not between 1 and 30 or not private.valid_avatar(p_avatar) then
    raise exception using errcode = 'P0001', message = 'invalid_profile';
  end if;

  update public.profiles
     set first_name = v_name, avatar = p_avatar, age_range = p_age_range, languages = coalesce(p_languages, '{}')
   where id = v_uid;

  update public.account_private
     set gender = nullif(p_gender, ''), interests = coalesce(p_interests, '{}')
   where user_id = v_uid;
end
$$;

create or replace function public.set_locale(p_locale text)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := private.require_user();
begin
  update public.account_private set locale = p_locale where user_id = v_uid;
end
$$;

-- ───────────────────────── spots ─────────────────────────

create or replace function public.create_spot(
  p_kind          text,
  p_type          text,
  p_title         text,
  p_venue_name    text,
  p_address       text,
  p_lat           double precision,
  p_lng           double precision,
  p_starts_at     timestamptz,
  p_ends_at       timestamptz,
  p_friends_count integer,
  p_friends_women integer,
  p_friends_men   integer,
  p_friends_other integer,
  p_places        integer,
  p_languages     text[],
  p_cost_note     text,
  p_needs_booking boolean,
  p_booking_note  text,
  p_host_note     text,
  p_find_us_hint  text
) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := private.require_user();
  v_id  uuid;
begin
  perform private.lock_user(v_uid);

  if p_starts_at is null or p_ends_at is null then
    raise exception using errcode = 'P0001', message = 'invalid_time';
  end if;
  if p_starts_at < now() + interval '10 minutes' then
    raise exception using errcode = 'P0001', message = 'starts_too_soon';
  end if;
  if p_starts_at > now() + interval '7 days' then
    raise exception using errcode = 'P0001', message = 'starts_too_far';
  end if;
  if p_ends_at < p_starts_at + interval '30 minutes' or p_ends_at > p_starts_at + interval '12 hours' then
    raise exception using errcode = 'P0001', message = 'invalid_duration';
  end if;

  if (select count(*) from public.spots s
       where s.host_id = v_uid and s.cancelled_at is null and s.ends_at > now()) >= 3 then
    raise exception using errcode = 'P0001', message = 'too_many_open_spots';
  end if;
  if (select count(*) from public.spots s
       where s.host_id = v_uid and s.created_at > now() - interval '24 hours') >= 5 then
    raise exception using errcode = 'P0001', message = 'daily_limit';
  end if;

  insert into public.spots (
    host_id, kind, type, title, venue_name, address, lat, lng, starts_at, ends_at,
    friends_count, friends_women, friends_men, friends_other, places, languages,
    cost_note, needs_booking, booking_note, host_note
  ) values (
    v_uid, p_kind, p_type, private.clean_line(p_title), private.clean_line(p_venue_name),
    private.clean_line(p_address), p_lat, p_lng, p_starts_at, p_ends_at,
    coalesce(p_friends_count, 0), coalesce(p_friends_women, 0), coalesce(p_friends_men, 0),
    coalesce(p_friends_other, 0), p_places, coalesce(p_languages, '{}'),
    private.clean_line(p_cost_note), coalesce(p_needs_booking, false),
    private.clean_text(p_booking_note), private.clean_text(p_host_note)
  )
  returning id into v_id;

  insert into public.spot_private (spot_id, find_us_hint)
  values (v_id, private.clean_text(p_find_us_hint));

  return v_id;
end
$$;

-- The host edits a spot that has not started. Changing the time or the place tells
-- everyone who is in the group or waiting for an answer.
create or replace function public.update_spot(
  p_spot_id       uuid,
  p_type          text,
  p_title         text,
  p_venue_name    text,
  p_address       text,
  p_lat           double precision,
  p_lng           double precision,
  p_starts_at     timestamptz,
  p_ends_at       timestamptz,
  p_friends_count integer,
  p_friends_women integer,
  p_friends_men   integer,
  p_friends_other integer,
  p_places        integer,
  p_languages     text[],
  p_cost_note     text,
  p_needs_booking boolean,
  p_booking_note  text,
  p_host_note     text,
  p_find_us_hint  text
) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid     uuid := private.require_user();
  v_spot    public.spots;
  v_venue   text := private.clean_line(p_venue_name);
  v_address text := private.clean_line(p_address);
  v_moved   boolean;
begin
  select * into v_spot from public.spots where id = p_spot_id and host_id = v_uid for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'spot_not_found';
  end if;
  if v_spot.cancelled_at is not null then
    raise exception using errcode = 'P0001', message = 'spot_cancelled';
  end if;
  if v_spot.starts_at <= clock_timestamp() then
    raise exception using errcode = 'P0001', message = 'spot_started';
  end if;

  if p_starts_at is null or p_ends_at is null then
    raise exception using errcode = 'P0001', message = 'invalid_time';
  end if;
  if p_starts_at is distinct from v_spot.starts_at then
    if p_starts_at < now() + interval '10 minutes' then
      raise exception using errcode = 'P0001', message = 'starts_too_soon';
    end if;
    if p_starts_at > now() + interval '7 days' then
      raise exception using errcode = 'P0001', message = 'starts_too_far';
    end if;
  end if;
  if p_ends_at < p_starts_at + interval '30 minutes' or p_ends_at > p_starts_at + interval '12 hours' then
    raise exception using errcode = 'P0001', message = 'invalid_duration';
  end if;
  if p_places < private.active_member_count(p_spot_id) then
    raise exception using errcode = 'P0001', message = 'places_below_joined';
  end if;

  v_moved := p_starts_at is distinct from v_spot.starts_at
          or p_ends_at   is distinct from v_spot.ends_at
          or v_venue     is distinct from v_spot.venue_name
          or v_address   is distinct from v_spot.address
          or p_lat       is distinct from v_spot.lat
          or p_lng       is distinct from v_spot.lng;

  update public.spots set
    type = p_type, title = private.clean_line(p_title), venue_name = v_venue, address = v_address,
    lat = p_lat, lng = p_lng, starts_at = p_starts_at, ends_at = p_ends_at,
    friends_count = coalesce(p_friends_count, 0), friends_women = coalesce(p_friends_women, 0),
    friends_men = coalesce(p_friends_men, 0), friends_other = coalesce(p_friends_other, 0),
    places = p_places, languages = coalesce(p_languages, '{}'),
    cost_note = private.clean_line(p_cost_note), needs_booking = coalesce(p_needs_booking, false),
    booking_note = private.clean_text(p_booking_note), host_note = private.clean_text(p_host_note)
  where id = p_spot_id;

  update public.spot_private set find_us_hint = private.clean_text(p_find_us_hint) where spot_id = p_spot_id;

  if v_moved then
    perform private.notify(m.user_id, 'spot_changed', p_spot_id)
      from public.memberships m where m.spot_id = p_spot_id and m.status = 'active';
    perform private.notify(r.requester_id, 'spot_changed', p_spot_id)
      from public.join_requests r where r.spot_id = p_spot_id and r.status = 'pending';
  end if;
end
$$;

-- Caller must already hold the spot's row lock and have checked permission.
create or replace function private.cancel_spot_locked(p_spot_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  update public.spots set cancelled_at = now() where id = p_spot_id and cancelled_at is null;
  if not found then
    return;
  end if;

  perform private.notify(m.user_id, 'spot_cancelled', p_spot_id)
    from public.memberships m where m.spot_id = p_spot_id and m.status = 'active';
  perform private.notify(r.requester_id, 'spot_cancelled', p_spot_id)
    from public.join_requests r where r.spot_id = p_spot_id and r.status = 'pending';

  -- Requests that were still waiting can no longer be answered.
  delete from public.notifications n
   using public.join_requests r
   where n.request_id = r.id and n.type = 'request_received'
     and r.spot_id = p_spot_id and r.status = 'pending';
  update public.join_requests set status = 'expired', decided_at = now()
   where spot_id = p_spot_id and status = 'pending';
end
$$;

create or replace function public.cancel_spot(p_spot_id uuid)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid  uuid := private.require_user();
  v_spot public.spots;
begin
  select * into v_spot from public.spots where id = p_spot_id and host_id = v_uid for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'spot_not_found';
  end if;
  if v_spot.cancelled_at is not null then
    return;
  end if;
  if v_spot.ends_at <= clock_timestamp() then
    raise exception using errcode = 'P0001', message = 'spot_ended';
  end if;
  perform private.cancel_spot_locked(p_spot_id);
end
$$;

-- ───────────────────────── requests ─────────────────────────

create or replace function public.request_to_join(p_spot_id uuid, p_message text)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_uid  uuid := private.require_user();
  v_spot public.spots;
  v_id   uuid;
begin
  perform private.lock_user(v_uid);

  select * into v_spot from public.spots where id = p_spot_id;
  -- A spot the caller may not see is reported exactly like one that does not exist.
  if not found or not private.can_see_spot(p_spot_id, v_uid) then
    raise exception using errcode = 'P0001', message = 'spot_not_found';
  end if;
  if v_spot.host_id = v_uid then
    raise exception using errcode = 'P0001', message = 'own_spot';
  end if;
  if v_spot.cancelled_at is not null then
    raise exception using errcode = 'P0001', message = 'spot_cancelled';
  end if;
  if v_spot.starts_at <= clock_timestamp() then
    raise exception using errcode = 'P0001', message = 'spot_started';
  end if;

  if exists (select 1 from public.memberships m
              where m.spot_id = p_spot_id and m.user_id = v_uid and m.status = 'active') then
    raise exception using errcode = 'P0001', message = 'already_member';
  end if;
  if exists (select 1 from public.memberships m where m.spot_id = p_spot_id and m.user_id = v_uid) then
    raise exception using errcode = 'P0001', message = 'cannot_rejoin';
  end if;
  if exists (select 1 from public.join_requests r
              where r.spot_id = p_spot_id and r.requester_id = v_uid and r.status = 'pending') then
    raise exception using errcode = 'P0001', message = 'already_requested';
  end if;
  if exists (select 1 from public.join_requests r
              where r.spot_id = p_spot_id and r.requester_id = v_uid and r.status = 'declined') then
    raise exception using errcode = 'P0001', message = 'already_answered';
  end if;
  if (select count(*) from public.join_requests r
       where r.spot_id = p_spot_id and r.requester_id = v_uid and r.status = 'withdrawn') >= 2 then
    raise exception using errcode = 'P0001', message = 'too_many_requests';
  end if;

  if private.active_member_count(p_spot_id) >= v_spot.places then
    raise exception using errcode = 'P0001', message = 'spot_full';
  end if;

  if (select count(*) from public.join_requests r
       where r.requester_id = v_uid and r.status = 'pending') >= 5 then
    raise exception using errcode = 'P0001', message = 'too_many_pending';
  end if;
  if (select count(*) from public.join_requests r
       where r.requester_id = v_uid and r.created_at > now() - interval '24 hours') >= 10 then
    raise exception using errcode = 'P0001', message = 'daily_limit';
  end if;

  begin
    insert into public.join_requests (spot_id, requester_id, message)
    values (p_spot_id, v_uid, private.clean_text(p_message))
    returning id into v_id;
  exception when unique_violation then
    raise exception using errcode = 'P0001', message = 'already_requested';
  end;

  perform private.notify(v_spot.host_id, 'request_received', p_spot_id, v_id);
  return v_id;
end
$$;

create or replace function public.withdraw_request(p_request_id uuid)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := private.require_user();
begin
  update public.join_requests
     set status = 'withdrawn', message = '', decided_at = now()
   where id = p_request_id and requester_id = v_uid and status = 'pending';
  if not found then
    raise exception using errcode = 'P0001', message = 'request_not_pending';
  end if;
  delete from public.notifications where request_id = p_request_id and type = 'request_received';
end
$$;

-- The host answers a request. Accepting is atomic: host, pending request, spot not
-- started or cancelled, no block, and a free place are all checked while the spot is locked.
create or replace function public.decide_request(p_request_id uuid, p_accept boolean)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid     uuid := private.require_user();
  v_spot_id uuid;
  v_spot    public.spots;
  v_req     public.join_requests;
begin
  if p_accept is null then
    raise exception using errcode = 'P0001', message = 'invalid_decision';
  end if;

  select r.spot_id into v_spot_id
    from public.join_requests r
    join public.spots s on s.id = r.spot_id
   where r.id = p_request_id and s.host_id = v_uid;
  if not found then
    raise exception using errcode = 'P0001', message = 'request_not_found';
  end if;

  select * into v_spot from public.spots where id = v_spot_id for update;
  select * into v_req  from public.join_requests where id = p_request_id for update;

  if v_spot.host_id <> v_uid then
    raise exception using errcode = 'P0001', message = 'request_not_found';
  end if;
  if v_req.status <> 'pending' then
    raise exception using errcode = 'P0001', message = 'request_not_pending';
  end if;
  if v_spot.cancelled_at is not null then
    raise exception using errcode = 'P0001', message = 'spot_cancelled';
  end if;
  if v_spot.starts_at <= clock_timestamp() then
    raise exception using errcode = 'P0001', message = 'spot_started';
  end if;

  if p_accept then
    if private.blocked_between(v_uid, v_req.requester_id) or not private.is_onboarded(v_req.requester_id) then
      raise exception using errcode = 'P0001', message = 'request_not_found';
    end if;
    if private.active_member_count(v_spot_id) >= v_spot.places then
      raise exception using errcode = 'P0001', message = 'spot_full';
    end if;

    insert into public.memberships (spot_id, user_id, request_id)
    values (v_spot_id, v_req.requester_id, v_req.id);
    update public.join_requests set status = 'accepted', decided_at = now() where id = v_req.id;
    perform private.notify(v_req.requester_id, 'request_accepted', v_spot_id, v_req.id);
  else
    update public.join_requests set status = 'declined', decided_at = now() where id = v_req.id;
    perform private.notify(v_req.requester_id, 'request_declined', v_spot_id, v_req.id);
  end if;

  delete from public.notifications where request_id = v_req.id and type = 'request_received';
end
$$;

-- ───────────────────────── leaving and removing ─────────────────────────

-- "Leave quietly": no chat message and no notice to the other members. The place
-- opens again, and before the start the host gets a neutral "a place opened up".
create or replace function public.leave_spot(p_spot_id uuid)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid  uuid := private.require_user();
  v_spot public.spots;
begin
  select * into v_spot from public.spots where id = p_spot_id for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'not_member';
  end if;

  update public.memberships set status = 'left', ended_at = now()
   where spot_id = p_spot_id and user_id = v_uid and status = 'active';
  if not found then
    raise exception using errcode = 'P0001', message = 'not_member';
  end if;

  delete from public.notifications where user_id = v_uid and spot_id = p_spot_id and type = 'new_message';

  if v_spot.cancelled_at is null and v_spot.starts_at > clock_timestamp() then
    perform private.notify(v_spot.host_id, 'place_opened', p_spot_id);
  end if;
end
$$;

create or replace function public.remove_member(p_spot_id uuid, p_user_id uuid)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid  uuid := private.require_user();
  v_spot public.spots;
begin
  select * into v_spot from public.spots where id = p_spot_id and host_id = v_uid for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'spot_not_found';
  end if;
  if v_spot.ends_at <= clock_timestamp() then
    raise exception using errcode = 'P0001', message = 'spot_ended';
  end if;

  update public.memberships set status = 'removed', ended_at = now()
   where spot_id = p_spot_id and user_id = p_user_id and status = 'active';
  if not found then
    raise exception using errcode = 'P0001', message = 'not_member';
  end if;

  delete from public.notifications where user_id = p_user_id and spot_id = p_spot_id and type = 'new_message';
  perform private.notify(p_user_id, 'member_removed', p_spot_id);
end
$$;

-- ───────────────────────── chat ─────────────────────────

create or replace function public.send_message(p_spot_id uuid, p_body text, p_client_id uuid)
returns public.messages
language plpgsql security definer set search_path = '' as $$
declare
  v_uid  uuid := private.require_user();
  v_body text := private.clean_text(p_body);
  v_spot public.spots;
  v_msg  public.messages;
begin
  if p_client_id is null or char_length(v_body) not between 1 and 1000 then
    raise exception using errcode = 'P0001', message = 'invalid_message';
  end if;
  perform private.lock_user(v_uid);

  select * into v_spot from public.spots where id = p_spot_id;
  if not found or not private.is_participant(p_spot_id, v_uid) then
    raise exception using errcode = 'P0001', message = 'not_member';
  end if;

  -- A retry of a message that already arrived returns the stored message.
  select * into v_msg from public.messages where sender_id = v_uid and client_id = p_client_id;
  if found then
    if v_msg.spot_id <> p_spot_id then
      raise exception using errcode = 'P0001', message = 'invalid_message';
    end if;
    return v_msg;
  end if;

  if v_spot.cancelled_at is not null then
    raise exception using errcode = 'P0001', message = 'spot_cancelled';
  end if;
  if clock_timestamp() > v_spot.ends_at + interval '12 hours' then
    raise exception using errcode = 'P0001', message = 'chat_closed';
  end if;
  if (select count(*) from public.messages m
       where m.sender_id = v_uid and m.created_at > now() - interval '1 minute') >= 30 then
    raise exception using errcode = 'P0001', message = 'slow_down';
  end if;

  insert into public.messages (spot_id, sender_id, body, client_id)
  values (p_spot_id, v_uid, v_body, p_client_id)
  returning * into v_msg;

  -- One unread notification per chat for everyone else in the group, skipping
  -- anyone blocked in either direction.
  insert into public.notifications (user_id, type, spot_id)
  select u.user_id, 'new_message', p_spot_id
    from (
      select v_spot.host_id as user_id
      union
      select m.user_id from public.memberships m where m.spot_id = p_spot_id and m.status = 'active'
    ) u
   where u.user_id <> v_uid
     and private.is_onboarded(u.user_id)
     and not private.blocked_between(u.user_id, v_uid)
  on conflict do nothing;

  return v_msg;
end
$$;

create or replace function public.mark_notifications_read(p_ids uuid[])
returns void
language sql security definer set search_path = '' as $$
  update public.notifications set read_at = now()
   where user_id = auth.uid() and id = any (p_ids) and read_at is null
$$;

create or replace function public.mark_chat_read(p_spot_id uuid)
returns void
language sql security definer set search_path = '' as $$
  update public.notifications set read_at = now()
   where user_id = auth.uid() and spot_id = p_spot_id and type = 'new_message' and read_at is null
$$;

create or replace function public.mark_all_notifications_read()
returns void
language sql security definer set search_path = '' as $$
  update public.notifications set read_at = now()
   where user_id = auth.uid() and read_at is null
$$;

-- ───────────────────────── ratings ─────────────────────────

-- Host and joiner rate each other, once, in the 7 days after the plan ends.
-- Only people who were in the group when it started take part.
create or replace function public.submit_rating(
  p_spot_id             uuid,
  p_ratee_id            uuid,
  p_stars               integer,
  p_felt_safe           text,
  p_matched_description text,
  p_tags                text[]
) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid  uuid := private.require_user();
  v_spot public.spots;
begin
  select * into v_spot from public.spots where id = p_spot_id;
  if not found or p_ratee_id is null or p_ratee_id = v_uid or v_spot.cancelled_at is not null then
    raise exception using errcode = 'P0001', message = 'rating_not_allowed';
  end if;
  if not (
       (v_spot.host_id = v_uid      and private.was_member_at_start(p_spot_id, p_ratee_id))
    or (v_spot.host_id = p_ratee_id and private.was_member_at_start(p_spot_id, v_uid))
  ) or not private.is_onboarded(p_ratee_id) then
    raise exception using errcode = 'P0001', message = 'rating_not_allowed';
  end if;
  if clock_timestamp() < v_spot.ends_at then
    raise exception using errcode = 'P0001', message = 'rating_not_open';
  end if;
  if clock_timestamp() > v_spot.ends_at + interval '7 days' then
    raise exception using errcode = 'P0001', message = 'rating_closed';
  end if;

  begin
    insert into public.ratings (spot_id, rater_id, ratee_id, stars, felt_safe, matched_description, tags)
    values (p_spot_id, v_uid, p_ratee_id, p_stars, nullif(p_felt_safe, ''), nullif(p_matched_description, ''),
            coalesce(p_tags, '{}'));
  exception when unique_violation then
    raise exception using errcode = 'P0001', message = 'already_rated';
  end;
end
$$;

-- ───────────────────────── blocking and reporting ─────────────────────────

-- Blocking is immediate and cuts every tie between the two people:
--   * neither sees the other's profile, spots, requests or messages (see the policies)
--   * waiting requests between them end
--   * host blocks a member: the member is removed
--   * member blocks the host: the member leaves
--   * two members: both stay in the group but cannot read each other
create or replace function public.block_user(p_user_id uuid)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := private.require_user();
begin
  if p_user_id is null or p_user_id = v_uid
     or not exists (select 1 from public.profiles where id = p_user_id) then
    raise exception using errcode = 'P0001', message = 'user_not_found';
  end if;
  perform private.lock_user(v_uid);
  if (select count(*) from public.blocks b
       where b.blocker_id = v_uid and b.created_at > now() - interval '24 hours') >= 50 then
    raise exception using errcode = 'P0001', message = 'daily_limit';
  end if;

  -- Lock every spot the two share, in a fixed order, before touching memberships.
  perform 1 from public.spots s
   where (s.host_id = v_uid     and private.has_history(s.id, p_user_id))
      or (s.host_id = p_user_id and private.has_history(s.id, v_uid))
   order by s.id
     for update;

  insert into public.blocks (blocker_id, blocked_id) values (v_uid, p_user_id)
  on conflict do nothing;

  -- My waiting requests on their spots: taken back.
  update public.join_requests r set status = 'withdrawn', message = '', decided_at = now()
    from public.spots s
   where r.spot_id = s.id and r.status = 'pending'
     and r.requester_id = v_uid and s.host_id = p_user_id;

  -- Their waiting requests on my spots: declined, without a notification.
  update public.join_requests r set status = 'declined', decided_at = now()
    from public.spots s
   where r.spot_id = s.id and r.status = 'pending'
     and r.requester_id = p_user_id and s.host_id = v_uid;

  -- They are in a group I host that has not ended: removed.
  update public.memberships m set status = 'removed', ended_at = now()
    from public.spots s
   where m.spot_id = s.id and m.status = 'active'
     and m.user_id = p_user_id and s.host_id = v_uid and s.ends_at > now();

  -- I am in a group they host that has not ended: I leave.
  update public.memberships m set status = 'left', ended_at = now()
    from public.spots s
   where m.spot_id = s.id and m.status = 'active'
     and m.user_id = v_uid and s.host_id = p_user_id and s.ends_at > now();

  -- Notifications that point from one of us to the other's spot or request.
  delete from public.notifications n
   using public.spots s
   where n.spot_id = s.id
     and ((n.user_id = v_uid and s.host_id = p_user_id) or (n.user_id = p_user_id and s.host_id = v_uid));
  delete from public.notifications n
   using public.join_requests r
   where n.request_id = r.id
     and ((n.user_id = v_uid and r.requester_id = p_user_id) or (n.user_id = p_user_id and r.requester_id = v_uid));
end
$$;

create or replace function public.unblock_user(p_user_id uuid)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := private.require_user();
begin
  delete from public.blocks where blocker_id = v_uid and blocked_id = p_user_id;
end
$$;

-- A report is private. It stays possible after leaving a group or blocking someone,
-- so it does not check what the reporter can currently see.
create or replace function public.submit_report(
  p_spot_id          uuid,
  p_reported_user_id uuid,
  p_reason           text,
  p_details          text
) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := private.require_user();
begin
  perform private.lock_user(v_uid);
  if p_spot_id is null and p_reported_user_id is null then
    raise exception using errcode = 'P0001', message = 'invalid_report';
  end if;
  if p_reported_user_id = v_uid then
    raise exception using errcode = 'P0001', message = 'invalid_report';
  end if;
  if p_spot_id is not null and not exists (select 1 from public.spots where id = p_spot_id) then
    raise exception using errcode = 'P0001', message = 'invalid_report';
  end if;
  if p_reported_user_id is not null and not exists (select 1 from public.profiles where id = p_reported_user_id) then
    raise exception using errcode = 'P0001', message = 'invalid_report';
  end if;
  if (select count(*) from public.reports r
       where r.reporter_id = v_uid and r.created_at > now() - interval '24 hours') >= 10 then
    raise exception using errcode = 'P0001', message = 'daily_limit';
  end if;

  insert into public.reports (reporter_id, reported_user_id, spot_id, reason, details)
  values (v_uid, p_reported_user_id, p_spot_id, p_reason, private.clean_text(p_details));
end
$$;

-- ───────────────────────── deleting an account ─────────────────────────

-- What happens, in order:
--   * plans I host that have not ended are cancelled (members are told)
--   * I leave groups that have not ended; my waiting requests are taken back
--   * the text of my chat messages, request messages, host notes and meeting hints is erased
--   * my notifications, my blocks, my private account row and ratings about me are deleted
--   * my profile is blanked (shown to others as "Deleted user")
--   * my sign-in is deleted
-- Kept: ratings I gave (they count toward other people's totals, with no name attached)
-- and reports, for 12 months, for safety review.
create or replace function public.delete_account()
returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_uid  uuid := auth.uid();
  v_spot record;
begin
  if v_uid is null then
    raise exception using errcode = 'P0001', message = 'not_signed_in';
  end if;
  perform private.lock_user(v_uid);

  perform 1 from public.spots s
   where s.ends_at > now()
     and (s.host_id = v_uid or private.is_active_member(s.id, v_uid))
   order by s.id
     for update;

  for v_spot in
    select s.id from public.spots s
     where s.host_id = v_uid and s.cancelled_at is null and s.ends_at > now()
     order by s.id
  loop
    perform private.cancel_spot_locked(v_spot.id);
  end loop;

  for v_spot in
    select s.id, s.host_id, (s.cancelled_at is null and s.starts_at > now()) as upcoming
      from public.memberships m
      join public.spots s on s.id = m.spot_id
     where m.user_id = v_uid and m.status = 'active' and s.ends_at > now()
     order by s.id
  loop
    update public.memberships set status = 'left', ended_at = now()
     where spot_id = v_spot.id and user_id = v_uid and status = 'active';
    if v_spot.upcoming then
      perform private.notify(v_spot.host_id, 'place_opened', v_spot.id);
    end if;
  end loop;

  delete from public.notifications n
   using public.join_requests r
   where n.request_id = r.id and r.requester_id = v_uid and n.type = 'request_received';
  update public.join_requests set status = 'withdrawn', decided_at = now()
   where requester_id = v_uid and status = 'pending';
  update public.join_requests set message = '' where requester_id = v_uid and message <> '';

  update public.messages set body = '', deleted_at = now() where sender_id = v_uid and deleted_at is null;
  update public.spots set host_note = '', booking_note = '', cost_note = '' where host_id = v_uid;
  update public.spot_private sp set find_us_hint = ''
    from public.spots s where s.id = sp.spot_id and s.host_id = v_uid;

  delete from public.notifications where user_id = v_uid;
  delete from public.ratings where ratee_id = v_uid;
  delete from public.blocks where blocker_id = v_uid or blocked_id = v_uid;
  delete from public.admins where user_id = v_uid;
  delete from public.account_private where user_id = v_uid;

  update public.profiles
     set first_name = '', avatar = '{}'::jsonb, age_range = null, languages = '{}',
         onboarded_at = null, deleted_at = now()
   where id = v_uid;

  delete from auth.users where id = v_uid;
end
$$;


-- ═══════════ 20261119150300_read_functions.sql ═══════════

-- Pull Up · 4 of 5 · totals that are safe to show
--
-- These return numbers only, never another person's rows. Each one first checks
-- that the caller is allowed to see the spot or the profile it is asked about.

create or replace function public.server_now()
returns timestamptz language sql stable set search_path = '' as $$ select now() $$;

-- Runs as the owner because it reads a value kept in the private schema.
create or replace function public.app_config()
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'terms_version', private.terms_version(),
    'min_lead_minutes', 10,
    'max_days_ahead', 7,
    'rating_window_days', 7,
    'city', 'haifa',
    'time_zone', 'Asia/Jerusalem'
  )
$$;

-- For each spot the caller can see: how many joined through Pull Up, how many places
-- are left, and the gender mix of the people who are Pull Up users (host and members).
-- "unstated" counts people who chose not to say. Friends outside the app are not
-- included here; the host's own count for them is on the spot row.
create or replace function public.spot_summaries(p_spot_ids uuid[])
returns table (
  spot_id     uuid,
  joined      integer,
  places_left integer,
  women       integer,
  men         integer,
  nonbinary   integer,
  unstated    integer
)
language sql stable security definer set search_path = '' as $$
  with me as (select auth.uid() as uid),
  visible as (
    select s.id, s.host_id, s.places
      from public.spots s, me
     where s.id = any (p_spot_ids[1:100])
       and private.can_see_spot(s.id, me.uid)
  ),
  people as (
    select v.id as spot_id, v.host_id as user_id, false as is_member from visible v
    union all
    select m.spot_id, m.user_id, true
      from public.memberships m
      join visible v on v.id = m.spot_id
     where m.status = 'active'
  )
  select v.id,
         count(*) filter (where p.is_member)::integer,
         greatest(v.places - count(*) filter (where p.is_member), 0)::integer,
         count(*) filter (where a.gender = 'woman')::integer,
         count(*) filter (where a.gender = 'man')::integer,
         count(*) filter (where a.gender = 'nonbinary')::integer,
         count(*) filter (where a.gender is null)::integer
    from visible v
    join people p on p.spot_id = v.id
    left join public.account_private a on a.user_id = p.user_id
   group by v.id, v.places
$$;

-- Trust summary for people whose profile the caller can see.
--   plans_joined  plans that started while the person was in the group (not proof they showed up)
--   plans_hosted  plans they hosted that started with at least one person joined
--   ratings_count ratings that count (see below)
--   rating_avg    only once there are 3 or more, so a single rating cannot be read off it
-- A rating counts once the other side has rated too, or the 7-day window has closed.
create or replace function public.trust_summaries(p_user_ids uuid[])
returns table (
  user_id           uuid,
  plans_joined      integer,
  plans_hosted      integer,
  ratings_count     integer,
  rating_avg        numeric,
  technion_verified boolean
)
language sql stable security definer set search_path = '' as $$
  with me as (select auth.uid() as uid),
  targets as (
    select p.id
      from public.profiles p, me
     where p.id = any (p_user_ids[1:100])
       and p.deleted_at is null
       and private.can_see_profile(p.id, me.uid)
  ),
  counted as (
    select r.ratee_id, r.stars
      from public.ratings r
      join public.spots s on s.id = r.spot_id
      join targets t on t.id = r.ratee_id
     where now() > s.ends_at + interval '7 days'
        or exists (
             select 1 from public.ratings back
              where back.spot_id = r.spot_id
                and back.rater_id = r.ratee_id
                and back.ratee_id = r.rater_id
           )
  )
  select t.id,
         (select count(*)::integer
            from public.memberships m
            join public.spots s on s.id = m.spot_id
           where m.user_id = t.id
             and s.cancelled_at is null
             and s.starts_at <= now()
             and m.joined_at <= s.starts_at
             and (m.status = 'active' or m.ended_at > s.starts_at)),
         (select count(*)::integer
            from public.spots s
           where s.host_id = t.id
             and s.cancelled_at is null
             and s.starts_at <= now()
             and exists (
                   select 1 from public.memberships m
                    where m.spot_id = s.id
                      and m.joined_at <= s.starts_at
                      and (m.status = 'active' or m.ended_at > s.starts_at))),
         (select count(*)::integer from counted c where c.ratee_id = t.id),
         (select case when count(*) >= 3 then round(avg(c.stars), 1) end
            from counted c where c.ratee_id = t.id),
         coalesce((select a.technion_verified_at is not null
                     from public.account_private a where a.user_id = t.id), false)
    from targets t
$$;

-- Who the caller can still rate, and until when.
create or replace function public.rating_tasks()
returns table (spot_id uuid, ratee_id uuid, closes_at timestamptz)
language sql stable security definer set search_path = '' as $$
  with me as (select auth.uid() as uid),
  open_spots as (
    select s.id, s.host_id, s.ends_at
      from public.spots s
     where s.cancelled_at is null
       and s.ends_at <= now()
       and s.ends_at > now() - interval '7 days'
  ),
  pairs as (
    -- I hosted: everyone who was in the group at the start
    select o.id as spot_id, m.user_id as ratee_id, o.ends_at
      from open_spots o
      join public.memberships m on m.spot_id = o.id, me
     where o.host_id = me.uid
       and private.was_member_at_start(o.id, m.user_id)
    union all
    -- I joined: the host
    select o.id, o.host_id, o.ends_at
      from open_spots o, me
     where o.host_id <> me.uid
       and private.was_member_at_start(o.id, me.uid)
  )
  select p.spot_id, p.ratee_id, p.ends_at + interval '7 days'
    from pairs p, me
   where private.is_onboarded(me.uid)
     and private.is_onboarded(p.ratee_id)
     and not exists (
           select 1 from public.ratings r
            where r.spot_id = p.spot_id and r.rater_id = me.uid and r.ratee_id = p.ratee_id)
$$;


-- ═══════════ 20261119150400_maintenance_and_grants.sql ═══════════

-- Pull Up · 5 of 5 · scheduled housekeeping, live updates, and the final grants

-- ───────────────────────── housekeeping ─────────────────────────
-- Runs every 5 minutes. Nothing here decides who may do what: a request on a plan
-- that has started is already refused by decide_request, and the app already shows
-- it as expired. This only writes that state down and sends the notifications.
create or replace function private.run_maintenance()
returns void
language plpgsql security definer set search_path = '' as $$
begin
  -- Requests that were still waiting when the plan started.
  with expired as (
    update public.join_requests r
       set status = 'expired', decided_at = now()
      from public.spots s
     where r.spot_id = s.id
       and r.status = 'pending'
       and s.starts_at <= now()
    returning r.id, r.requester_id, r.spot_id
  ),
  cleared as (
    delete from public.notifications n
     using expired e
     where n.request_id = e.id and n.type = 'request_received'
  )
  insert into public.notifications (user_id, type, spot_id, request_id)
  select e.requester_id, 'request_expired', e.spot_id, e.id
    from expired e
   where private.is_onboarded(e.requester_id)
  on conflict do nothing;

  -- "You can rate this plan now", once per person per plan.
  insert into public.notifications (user_id, type, spot_id)
  select u.user_id, 'rating_open', u.spot_id
    from (
      select s.id as spot_id, m.user_id
        from public.spots s
        join public.memberships m on m.spot_id = s.id
       where s.cancelled_at is null
         and s.ends_at <= now() and s.ends_at > now() - interval '7 days'
         and private.was_member_at_start(s.id, m.user_id)
      union
      select s.id, s.host_id
        from public.spots s
       where s.cancelled_at is null
         and s.ends_at <= now() and s.ends_at > now() - interval '7 days'
         and exists (select 1 from public.memberships m
                      where m.spot_id = s.id and private.was_member_at_start(s.id, m.user_id))
    ) u
   where private.is_onboarded(u.user_id)
  on conflict do nothing;

  -- Retention.
  delete from public.notifications where created_at < now() - interval '60 days';
  delete from public.reports where created_at < now() - interval '12 months';
end
$$;

create extension if not exists pg_cron;

select cron.unschedule(jobid) from cron.job where jobname = 'pull-up-maintenance';
select cron.schedule('pull-up-maintenance', '*/5 * * * *', 'select private.run_maintenance()');

-- ───────────────────────── live updates ─────────────────────────
-- Realtime delivers a change only to people whose SELECT policy allows the row.
alter publication supabase_realtime add table
  public.spots,
  public.join_requests,
  public.memberships,
  public.messages,
  public.notifications;

-- ───────────────────────── final grants ─────────────────────────
-- Functions are executable by everyone by default in Postgres, so close that first
-- and then open exactly the list the app calls.

revoke execute on all functions in schema public  from public, anon, authenticated;
revoke execute on all functions in schema private from public, anon, authenticated;

grant execute on function
  public.server_now(),
  public.app_config(),
  public.complete_onboarding(text, jsonb, text, text[], text, text[], text, boolean, text),
  public.update_profile(text, jsonb, text, text[], text, text[]),
  public.set_locale(text),
  public.create_spot(text, text, text, text, text, double precision, double precision, timestamptz, timestamptz,
                     integer, integer, integer, integer, integer, text[], text, boolean, text, text, text),
  public.update_spot(uuid, text, text, text, text, double precision, double precision, timestamptz, timestamptz,
                     integer, integer, integer, integer, integer, text[], text, boolean, text, text, text),
  public.cancel_spot(uuid),
  public.request_to_join(uuid, text),
  public.withdraw_request(uuid),
  public.decide_request(uuid, boolean),
  public.leave_spot(uuid),
  public.remove_member(uuid, uuid),
  public.send_message(uuid, text, uuid),
  public.mark_notifications_read(uuid[]),
  public.mark_chat_read(uuid),
  public.mark_all_notifications_read(),
  public.submit_rating(uuid, uuid, integer, text, text, text[]),
  public.block_user(uuid),
  public.unblock_user(uuid),
  public.submit_report(uuid, uuid, text, text),
  public.delete_account(),
  public.spot_summaries(uuid[]),
  public.trust_summaries(uuid[]),
  public.rating_tasks()
to authenticated;

-- Only the helpers that row level security policies call need to be reachable by the
-- signed-in role. The "private" schema is not exposed by the API in any case.
grant execute on function
  private.is_onboarded(uuid),
  private.is_admin(uuid),
  private.blocked_between(uuid, uuid),
  private.is_host(uuid, uuid),
  private.is_active_member(uuid, uuid),
  private.is_participant(uuid, uuid),
  private.has_history(uuid, uuid),
  private.can_see_profile(uuid, uuid)
to authenticated;

-- Check constraints run as whoever writes the row. Writes only happen inside the
-- functions above (as the owner), but keep these callable so a constraint can never
-- fail on permissions.
grant execute on function
  private.valid_avatar(jsonb),
  private.known_languages(),
  private.known_types()
to authenticated;


